class IntArray:
    """Educational backing-buffer model; Python slots hold references."""
    def __init__(self):
        self.slots = []
        self.size = 0

    def insert(self, i, value):
        if not 0 <= i <= self.size:
            raise IndexError(i)
        if self.size == len(self.slots):
            grown = [None] * max(1, 2 * len(self.slots))
            for j in range(self.size):
                grown[j] = self.slots[j]
            self.slots = grown
        for j in range(self.size, i, -1):
            self.slots[j] = self.slots[j - 1]
        self.slots[i] = value
        self.size += 1

    def append(self, value):
        self.insert(self.size, value)

    def get(self, i):
        if not 0 <= i < self.size:
            raise IndexError(i)
        return self.slots[i]

    def set(self, i, value):
        self.get(i)  # validate logical bounds
        self.slots[i] = value

    def erase(self, i):
        result = self.get(i)
        for j in range(i, self.size - 1):
            self.slots[j] = self.slots[j + 1]
        self.size -= 1
        self.slots[self.size] = None  # release the obsolete reference
        return result

    def values(self):
        return self.slots[:self.size]

def erase_at(values, i):
    # In-place stable deletion, without using a built-in deletion operation.
    if not 0 <= i < len(values):
        raise IndexError(i)
    removed = values[i]
    for j in range(i, len(values) - 1):
        values[j] = values[j + 1]
    values.pop()
    return removed

if __name__ == '__main__':
    a = IntArray()
    for x in [10, 20, 30]: a.append(x)
    a.insert(1, 15)
    assert a.erase(2) == 20
    assert a.values() == [10, 15, 30]

