#include <vector>
#include <stdexcept>
#include <cassert>
using namespace std;
// vector's length models allocated slots; n is the separate logical size.
class IntArray {
    vector<int> slots;
    int n = 0;
public:
    int size() const { return n; }
    int capacity() const { return static_cast<int>(slots.size()); }
    void insert(int i, int value) {
        if (i < 0 || i > n) throw out_of_range("index");
        if (n == capacity()) {
            vector<int> grown(n == 0 ? 1 : 2 * n);
            for (int j = 0; j < n; ++j) grown[j] = slots[j];
            slots.swap(grown);
        }
        for (int j = n; j > i; --j) slots[j] = slots[j - 1];
        slots[i] = value; ++n;
    }
    void append(int value) { insert(n, value); }
    int get(int i) const {
        if (i < 0 || i >= n) throw out_of_range("index");
        return slots[i];
    }
    void set(int i, int value) { get(i); slots[i] = value; }
    int erase(int i) {
        int result = get(i);
        for (int j = i; j < n - 1; ++j) slots[j] = slots[j + 1];
        slots[--n] = 0;
        return result;
    }
    vector<int> values() const { return vector<int>(slots.begin(), slots.begin() + n); }
};
int erase_at(vector<int>& values, int i) {
    if (i < 0 || i >= static_cast<int>(values.size())) throw out_of_range("index");
    int removed = values[i];
    for (int j = i; j + 1 < static_cast<int>(values.size()); ++j) values[j] = values[j + 1];
    values.pop_back(); return removed;
}
int main() {
    IntArray a;
    for (int x : {10, 20, 30}) a.append(x);
    a.insert(1, 15); assert(a.erase(2) == 20);
    assert(a.values() == vector<int>({10, 15, 30}));
}

