import java.util.Arrays;
class ArrayDemo {
    static class IntArray {
        private int[] slots = new int[0];
        private int size = 0;
        void insert(int i, int value) {
            if (i < 0 || i > size) throw new IndexOutOfBoundsException();
            if (size == slots.length) {
                int[] grown = new int[Math.max(1, 2 * slots.length)];
                for (int j = 0; j < size; j++) grown[j] = slots[j];
                slots = grown;
            }
            for (int j = size; j > i; j--) slots[j] = slots[j - 1];
            slots[i] = value; size++;
        }
        void append(int value) { insert(size, value); }
        int get(int i) {
            if (i < 0 || i >= size) throw new IndexOutOfBoundsException();
            return slots[i];
        }
        void set(int i, int value) { get(i); slots[i] = value; }
        int erase(int i) {
            int result = get(i);
            for (int j = i; j < size - 1; j++) slots[j] = slots[j + 1];
            slots[--size] = 0; return result;
        }
        int[] values() { return Arrays.copyOf(slots, size); }
    }
    public static void main(String[] args) {
        IntArray a = new IntArray();
        for (int x : new int[]{10, 20, 30}) a.append(x);
        a.insert(1, 15);
        if (a.erase(2) != 20 || !Arrays.equals(a.values(), new int[]{10,15,30})) throw new AssertionError();
    }
}

