class IntArray {
  slots: (number | null)[];
  size: number;
  constructor() { this.slots = []; this.size = 0; }
  insert(i: number, value: number) {
    if (!Number.isInteger(i) || i < 0 || i > this.size) throw new RangeError("index");
    if (this.size === this.slots.length) {
      const grown = new Array(Math.max(1, 2 * this.slots.length)).fill(null);
      for (let j = 0; j < this.size; j++) grown[j] = this.slots[j];
      this.slots = grown;
    }
    for (let j = this.size; j > i; j--) this.slots[j] = this.slots[j - 1];
    this.slots[i] = value; this.size++;
  }
  append(value: number) { this.insert(this.size, value); }
  get(i: number): number {
    if (!Number.isInteger(i) || i < 0 || i >= this.size) throw new RangeError("index");
    return this.slots[i]!;
  }
  set(i: number, value: number) { this.get(i); this.slots[i] = value; }
  erase(i: number) {
    const result = this.get(i);
    for (let j = i; j < this.size - 1; j++) this.slots[j] = this.slots[j + 1];
    this.slots[--this.size] = null;
    return result;
  }
  values() { return this.slots.slice(0, this.size); }
}
function eraseAt(values: number[], i: number) {
  if (!Number.isInteger(i) || i < 0 || i >= values.length) throw new RangeError("index");
  const removed = values[i];
  for (let j = i; j < values.length - 1; j++) values[j] = values[j + 1];
  values.pop();
  return removed;
}

